function homeCtrl($scope,mS){$scope.init=()=>{mS.getData("get","/Home/ReadGestionCantidad").then((function(response){0!=response.id?$scope.cantidad=response.data:toast.toastr("warning",response.message,response.titleSms)}))},$scope.init()}app.controller("homeCtrl",homeCtrl),homeCtrl.$inject=["$scope","mainService"];